const app = document.querySelector('#app');
const toast = document.querySelector('#toast');
const session = JSON.parse(localStorage.getItem('jigoku-session') || 'null');
let state = null, stream = null, tick = null, previewParticipantId = null, gmTab = 'progress', dismissedResultKey = null, freeTimeView = 'rest', narrativeScrollPending = false;

const esc = value => String(value ?? '').replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
const statusDisplayNames = Object.freeze({ COOLDOWN_EXTENSION: '【強奪】', ATTACK_DAMAGE_DOWN: '攻撃ダメージ低下', POISON: '毒', BURN: '火傷', TARGET_RESTRICTION: '対象制限' });
const statusDisplayName = value => statusDisplayNames[value] || value;
const playerFacingText = value => Object.entries(statusDisplayNames).reduce((text, [key, label]) => text.replaceAll(key, label), String(value ?? ''));
const narrativeText = value => esc(playerFacingText(value)).replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>');
const categoryName = value => ({ attack: '攻撃', defense: '防御', support: '補助', heal: '回復', interference: '妨害' }[value] || value);
const CURRENCY_TYPES = [['one', '壱', 1], ['two', '弐', 2], ['three', '参', 3], ['five', '伍', 5], ['seven', '漆', 7]];
const currencyCoinsLabel = coins => CURRENCY_TYPES.filter(([type]) => coins?.[type]).map(([type, label]) => `${label}×${coins[type]}`).join('、') || 'なし';
const phaseName = () => ({ LOBBY: '乗車受付', INTRODUCTION: '導入', SELF_INTRODUCTION: '自己紹介', GAME_GUIDE: 'ゲーム説明', PACK_SELECTION: 'パック選択', TURN_SELECTION: 'カード秘密選択', TURN_RESULT: 'ターン結果', STATION_RESULT: '駅結果', REWARD_NARRATION: '報酬発表', CURRENCY_SYNC_WAIT: '冥貨反映待機', FREE_TIME_INTRO: '自由時間の案内', FREE_TIME: '自由時間・休憩', STATION_INTRODUCTION: '駅導入' }[state.phase]);
const narrativeStep = value => value?.phase === 'INTRODUCTION' ? value.introductionStep : value?.phase === 'GAME_GUIDE' ? value.gameGuide?.step : value?.phase === 'STATION_INTRODUCTION' ? value.stationIntroduction?.step : value?.phase === 'REWARD_NARRATION' ? value.rewardNarration?.step : value?.phase === 'FREE_TIME_INTRO' ? value.freeTimeIntroduction?.step : null;
const narrativeProgressed = (before, after) => Boolean(before && before.phase === after?.phase && narrativeStep(before) !== null && narrativeStep(after) > narrativeStep(before));
const INTRODUCTION_LINES = [
  'ガタン、ガタン。',
  '規則正しい揺れと、車輪が線路を擦る音。',
  '目を開けると、そこは見知らぬ列車の中だった。窓の外には、景色らしい景色はない。',
  'そして車内には、自分を含め、七人の人間がいた。',
  '誰も、この列車に乗った覚えはない。',
  'どうしてここにいるのか。どこへ向かっているのか。',
  '何ひとつ分からないまま、列車だけが進み続けている。',
  'そのとき、勢いよく車両の扉が開いた。',
  '「はぁ〜い！」',
  '「みなさ〜ん！ お目覚めですかぁ？」',
  '現れたのは、小さな角を生やした奇妙な生き物だった。',
  '車掌帽をかぶり、ぶかぶかの制服を着ている。その手には、人数分の切符が握られていた。',
  '「いやぁ〜、よかったよかった！」',
  '「七名様、ちゃ〜んと揃ってますねぇ！」',
  '「それでは改めまして」',
  '小鬼は帽子を押さえ、深々と頭を下げる。',
  '「ようこそ！地獄廻線へ！」',
  '聞き慣れない言葉が、車内に響く。',
  '「この列車はこれから、七つの地獄を順番に巡りま〜す！」',
  '「焦熱、氷結、針山、血の池、餓鬼、修羅……」',
  '「そして最後は、無間地獄！」',
  '「いやぁ、観光列車みたいで楽しそうですねぇ！」',
  '小鬼は楽しそうに笑う。',
  '「あっ、大事なことを忘れてました！」',
  '「みなさん……」',
  '少しだけ間を置いて。',
  '「もう死んでますからねぇ。」',
  '「なのでぇ、ここから先は生きてた頃の常識なんて、あんまり役に立ちませ〜ん！」',
  '「七つの地獄を巡って、最後までちゃ〜んと乗っていてくださいね！」',
  'その直後。車内放送のチャイムが鳴る。',
  '――ピンポーン。',
  '『まもなく――第一地獄。』',
  '『焦熱地獄。』',
  '「さぁ！」',
  '「その前に、せっかく七人もいるんですから」',
  '「まずは、お互いのことを知っておきましょうか！」',
  'こうして。',
  '行き先も、降り方も分からないまま。',
  '七人を乗せた地獄廻線は、最初の駅へと走り始めた。'
];
const mePublic = id => state.players.find(player => player.participantId === id);
const cardName = id => state.packs.flatMap(pack => pack.cards || []).find(card => card.id === id)?.name || id || 'なし';
const playerName = id => { const player = mePublic(id); return player ? `PL${player.playerNumber} ${player.name}` : '対象なし'; };
const currencySummary = currency => [['one', '壱'], ['two', '弐'], ['three', '参'], ['five', '伍'], ['seven', '漆']].filter(([key]) => Number(currency?.[key]) > 0).map(([key, label]) => `${label} ${currency[key]}`).join('｜') || 'なし';

function notify(message) { toast.textContent = message; toast.style.display = 'block'; setTimeout(() => toast.style.display = 'none', 3500); }
async function request(path, options = {}) { const response = await fetch(path, { ...options, headers: { 'content-type': 'application/json', ...(session?.token ? { authorization: `Bearer ${session.token}` } : {}) } }); const data = await response.json(); if (!response.ok) throw new Error(data.error); return data; }
function saveSession(data) { localStorage.setItem('jigoku-session', JSON.stringify(data)); location.reload(); }
async function action(type, payload = {}) { try { const previous = state; const nextState = await request(`/api/rooms/${session.roomCode}/actions`, { method: 'POST', body: JSON.stringify({ type, ...payload }) }); narrativeScrollPending ||= narrativeProgressed(previous, nextState); state = nextState; render(); } catch (error) { notify(error.message); } }

document.querySelector('#createForm')?.addEventListener('submit', async event => { event.preventDefault(); try { saveSession(await request('/api/rooms', { method: 'POST', body: JSON.stringify({ name: new FormData(event.target).get('name') }) })); } catch (error) { notify(error.message); } });
document.querySelector('#testRoom')?.addEventListener('click', async () => { try { saveSession(await request('/api/test-room', { method: 'POST', body: '{}' })); } catch (error) { notify(error.message); } });
document.querySelector('#joinForm')?.addEventListener('submit', async event => { event.preventDefault(); const form = new FormData(event.target); try { saveSession(await request(`/api/rooms/${form.get('code').toUpperCase()}/join`, { method: 'POST', body: JSON.stringify({ name: form.get('name') }) })); } catch (error) { notify(error.message); } });

async function connect() { if (!session) return; try { state = await request(`/api/rooms/${session.roomCode}/state`); render(); const issued = await request(`/api/rooms/${session.roomCode}/stream-ticket`, { method: 'POST', body: '{}' }); stream = new EventSource(`/api/rooms/${session.roomCode}/events?ticket=${encodeURIComponent(issued.ticket)}`); stream.addEventListener('state', event => { const previous = state; const nextState = JSON.parse(event.data); narrativeScrollPending ||= narrativeProgressed(previous, nextState); state = nextState; render(); }); stream.onerror = () => {}; } catch (error) { localStorage.removeItem('jigoku-session'); notify(error.message); setTimeout(() => location.reload(), 1200); } }

function timerHtml(compact = false) { if (!state.timer) return '<span class="timer-empty">--:--</span>'; const remaining = Math.max(0, Math.ceil((state.timer.endsAt - Date.now()) / 1000)); return `<span class="timer ${compact ? 'compact' : ''} ${remaining <= 30 ? 'warning' : ''}">${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, '0')}</span>`; }
function gameHeaderHtml(roleLabel) { const station = state.station; const turn = state.phase === 'STATION_INTRODUCTION' ? `— / ${station?.turnCount || '—'}` : station ? `${state.stationTurn} / ${station.turnCount}` : '—'; return `<section class="game-header"><div><span class="eyebrow">${esc(roleLabel)}</span><strong>${station ? esc(station.name) : phaseName()}</strong></div><div class="header-stat"><span>TURN</span><b>${turn}</b></div><div class="header-stat"><span>PHASE</span><b>${phaseName()}</b></div><div class="header-stat timer-stat"><span>TIME</span>${timerHtml(true)}</div>${station ? `<div class="station-effect"><span>駅効果</span><b>${esc(station.effect)}</b></div>` : ''}</section>`; }

function introductionHtml() { return `<section class="panel script"><span class="eyebrow">導入「地獄廻線」</span><h2>地獄廻線</h2>${INTRODUCTION_LINES.map((line, index) => `<p ${index >= state.introductionStep ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function applyIntroductionProgress() { if (state.phase !== 'INTRODUCTION') return; document.querySelectorAll('.script').forEach(script => { script.querySelectorAll(':scope > p').forEach((element, index) => { element.hidden = index >= state.introductionStep; }); }); }
function introductionAdvanceHtml() { return `<div class="actions intro-actions"><button id="advanceIntro">${state.introductionStep >= INTRODUCTION_LINES.length ? '自己紹介8分へ' : '次へ'}</button></div>`; }
function gameGuideHtml() { const guide = state.gameGuide; if (!guide) return ''; return `<section class="panel script"><span class="eyebrow">${esc(guide.title)}</span><h2>${esc(guide.title)}</h2>${guide.lines.map((line, index) => `<p ${index >= guide.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function gameGuideAdvanceHtml() { const guide = state.gameGuide; if (!guide) return ''; return `<div class="actions intro-actions"><button id="advanceGameGuide">${guide.step >= guide.lines.length ? 'パック選択へ' : '次へ'}</button></div>`; }
function stationIntroductionHtml() { const introduction = state.stationIntroduction; if (!introduction) return ''; return `<section class="panel script station-script"><span class="eyebrow">${esc(introduction.title)}</span><h2>${esc(state.station?.name || '')}</h2>${introduction.lines.map((line, index) => `<p data-station-line ${index >= introduction.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function stationIntroductionAdvanceHtml() { const introduction = state.stationIntroduction; if (!introduction) return ''; return `<div class="actions intro-actions"><button id="advanceStationIntro">${introduction.step >= introduction.lines.length ? `${esc(state.station.name)}を開始` : '次へ'}</button></div>`; }
function rewardNarrationHtml() { const narration = state.rewardNarration; if (!narration) return ''; return `<section class="panel script reward-script"><span class="eyebrow">報酬発表</span><h2>${esc(narration.title)}</h2>${narration.lines.map((line, index) => `<p ${index >= narration.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function rewardNarrationAdvanceHtml() { const narration = state.rewardNarration; if (!narration) return ''; return `<div class="actions intro-actions"><button id="advanceRewardNarration">${narration.step >= narration.lines.length ? '冥貨反映待機へ' : '次へ'}</button></div>`; }
function freeTimeIntroductionHtml() { const narration = state.freeTimeIntroduction; if (!narration) return ''; return `<section class="panel script reward-script"><span class="eyebrow">自由時間</span><h2>${esc(narration.title)}</h2>${narration.lines.map((line, index) => `<p ${index >= narration.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function freeTimeIntroductionAdvanceHtml() { const narration = state.freeTimeIntroduction; if (!narration) return ''; return `<div class="actions intro-actions"><button id="advanceFreeTimeIntroduction">${narration.step >= narration.lines.length ? '自由時間を開始' : '次へ'}</button></div>`; }
function rewardSummaryHtml(result = state.stationResult) { if (!result?.rewardSummary) return ''; return `<div class="reward-summary">${result.rewardSummary.map(entry => { const player = state.players.find(item => item.participantId === entry.participantId); return `<article><b>PL${entry.playerNumber} ${esc(player?.name || '')}</b><span>順位：${entry.rank ? `${entry.rank}位` : '対象外'}</span><span>順位報酬：壱×${entry.rankReward}</span><span>支援賞：壱×${entry.supportAward}</span><span>特殊ボーナス：壱×${entry.specialBonus}</span><strong>合計：壱×${entry.totalOne}</strong></article>`; }).join('')}</div>`; }
function currencySyncWaitHtml(me) { const reward = state.stationResult?.rewardSummary?.find(entry => entry.participantId === me.participantId); return `<section class="focus-panel currency-sync-wait"><span class="eyebrow">COCOFORIA SYNC</span><h2>冥貨の反映待機</h2><p>GMが今回獲得した冥貨をココフォリアへ反映しています。しばらくお待ちください。</p><div class="earned-currency"><span>今回の獲得</span><strong>壱×${reward?.totalOne || 0}</strong></div><p class="meta">反映が完了するまで、ショップ購入・冥貨譲渡・次駅への進行はできません。</p>${rewardSummaryHtml()}</section>`; }
function selfIntroductionHtml(viewerId = null) { const viewer = viewerId ? mePublic(viewerId) : null; const completion = viewer ? (viewer.selfIntroductionComplete ? '<p class="success-message">自己紹介完了を送信しました。全員の完了をお待ちください。</p>' : `<button class="primary-action" ${state.me.role === 'GM' ? `data-test-self-intro="${viewerId}"` : 'id="selfIntroDone"'}>自己紹介終わった</button>`) : ''; return `<section class="focus-panel"><span class="eyebrow">CURRENT ACTION</span><h2>自己紹介をしてください</h2><div class="intro-timer">${timerHtml()}</div><p>終わったPLから完了ボタンを押してください。</p><div class="compact-players">${state.players.map(player => `<div><b>PL${player.playerNumber} ${esc(player.name)}</b><span class="pill ${player.selfIntroductionComplete ? 'confirmed' : 'pending'}">${player.selfIntroductionComplete ? '完了' : '進行中'}</span></div>`).join('')}</div>${completion}</section>`; }

function scrollNarrativeIntoView() { const target = document.querySelector('.intro-actions') || [...document.querySelectorAll('.script > p')].filter(line => !line.hidden).at(-1); target?.scrollIntoView({ behavior: 'smooth', block: 'end' }); }
function render() { if (!state) return; base(); if (state.me.role === 'GM') renderGm(); else renderPlayer(); bindFreeTimeNavigation(); showResultModal(); showPurchaseModal(); applyIntroductionProgress(); if (narrativeScrollPending) { narrativeScrollPending = false; requestAnimationFrame(scrollNarrativeIntoView); } clearInterval(tick); tick = setInterval(updateTimer, 1000); }
function updateTimer() { document.querySelectorAll('.timer').forEach(old => { old.outerHTML = timerHtml(old.classList.contains('compact')); }); const finish = document.querySelector('#openPacks'); if (finish && state.timer && Date.now() >= state.timer.endsAt) { finish.disabled = false; finish.textContent = '自己紹介を終了してパック選択へ'; } }
function base() { document.querySelector('#roomBadge').innerHTML = `<span class="pill">ROOM ${esc(state.code)}</span> <button class="secondary small" id="leave">退出</button>`; setTimeout(() => document.querySelector('#leave')?.addEventListener('click', () => { localStorage.removeItem('jigoku-session'); location.reload(); }), 0); }

function renderPlayer() { const me = state.me; if (state.phase === 'LOBBY') return renderSimple(`<h2>乗車待機中</h2><p>PL${me.playerNumber} ${esc(me.name)}</p><p>参加者 ${state.players.length}/7。GMの開始をお待ちください。</p>`); if (state.phase === 'INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + introductionHtml(); return; } if (state.phase === 'GAME_GUIDE') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + gameGuideHtml(); return; } if (state.phase === 'STATION_INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + stationIntroductionHtml(); return; } if (state.phase === 'SELF_INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + selfIntroductionHtml(me.participantId); bindPlayer(); return; } if (state.phase === 'PACK_SELECTION') return renderPackSelection(me, false); if (state.phase === 'STATION_RESULT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + stationResultHtml(); return; } if (state.phase === 'REWARD_NARRATION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + rewardNarrationHtml(); return; } if (state.phase === 'CURRENCY_SYNC_WAIT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + currencySyncWaitHtml(me); return; } if (state.phase === 'FREE_TIME_INTRO') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + freeTimeIntroductionHtml(); return; } if (state.phase === 'FREE_TIME') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + freeTimeHtml(me); return; } renderTurnPlayer(me, false); }
function renderPlayerPreview() { const me = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (!me) { previewParticipantId = null; return renderGm(); } const back = '<button id="previewBack" class="secondary preview-back">← GM画面へ戻る</button>'; if (state.phase === 'INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + introductionHtml(); else if (state.phase === 'GAME_GUIDE') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + gameGuideHtml(); else if (state.phase === 'STATION_INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + stationIntroductionHtml(); else if (state.phase === 'SELF_INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + selfIntroductionHtml(me.participantId); else if (state.phase === 'PACK_SELECTION') { renderPackSelection(me, true); app.insertAdjacentHTML('afterbegin', back); } else if (state.phase === 'LOBBY') app.innerHTML = back + '<section class="panel"><h2>乗車待機中</h2></section>'; else if (state.phase === 'STATION_RESULT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + stationResultHtml(); else if (state.phase === 'REWARD_NARRATION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + rewardNarrationHtml(); else if (state.phase === 'CURRENCY_SYNC_WAIT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + currencySyncWaitHtml(me); else if (state.phase === 'FREE_TIME_INTRO') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + freeTimeIntroductionHtml(); else if (state.phase === 'FREE_TIME') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + freeTimeHtml(me); else { renderTurnPlayer(me, true); app.insertAdjacentHTML('afterbegin', back); } bindPreview(me); }
function renderSimple(content) { app.innerHTML = `<section class="panel welcome">${content}</section>`; }

function renderPackSelection(me, preview) { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}${preview ? ' TEST VIEW' : ''}`) + packSelectionHtml(me, preview); bindPack(me, preview); }
function packSelectionHtml(me, preview) { const pack = state.packs.find(item => item.id === me.packId); const confirmed = mePublic(me.participantId)?.confirmed; const unselected = state.players.filter(player => !player.packId).map(player => `PL${player.playerNumber}`).join('、') || 'なし'; return `<section class="focus-panel"><span class="step-label">現在の操作</span><h2>カードパックを選択</h2><p>選択中：<b>${esc(pack?.name || '未選択')}</b>${confirmed ? '（確定済み）' : ''}</p><p class="meta">ほかのPLと同じパックも選択できます。全員確定後、7種類が重複していない場合にゲームを開始できます。</p><p class="pack-unselected">未選択：${esc(unselected)}</p><div class="pack-grid">${state.packs.map(item => { const selectors = state.players.filter(player => player.packId === item.id); return `<article class="choice-card ${me.packId === item.id ? 'selected' : ''} ${selectors.length > 1 ? 'duplicated' : ''}"><span class="category">${esc(item.specialty)}</span><h3>${esc(item.name)}</h3><div class="pack-selectors">${selectors.length ? selectors.map(player => `<span class="pill ${player.confirmed ? 'confirmed' : 'pending'}">PL${player.playerNumber} ${esc(player.name)}${player.confirmed ? ' ✓' : ''}</span>`).join('') : '<span>選択者なし</span>'}</div><button data-pack-choice="${item.id}" ${confirmed ? 'disabled' : ''}>${me.packId === item.id ? '選択中' : '選択する'}</button></article>`; }).join('')}</div><div class="actions">${me.packId ? '<button type="button" id="packClear" class="secondary">選択を解除</button>' : ''}<button id="packConfirm" class="primary-action" ${!me.packId || confirmed || preview ? 'disabled' : ''}>このパックで最終確認</button></div></section>`; }

function renderTurnPlayer(me, preview) { const publicMe = mePublic(me.participantId); app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}${preview ? ' TEST VIEW' : ''}`) + (state.phase === 'TURN_RESULT' ? turnResultHtml(me) : publicMe.confirmed ? waitingHtml(me) : selectionWorkspaceHtml(me)); bindTurn(me, preview); }
function selectionWorkspaceHtml(me) { const publicMe = mePublic(me.participantId); const selected = publicMe.selection; return `<div class="play-layout"><aside class="side-column"><section class="panel compact-panel"><h2>他のPL</h2>${otherPlayersHtml(me.participantId)}</section><section class="status-card"><span>YOUR STATUS</span><h2>PL${me.playerNumber} ${esc(me.name)}</h2><div class="hp-large"><small>HP</small>${me.hp}<em>/ 15</em></div>${publicMe.isDeadState ? '<div class="dead-banner">亡者状態</div>' : '<div class="alive-banner">通常状態</div>'}<p class="meta">パック：${esc(state.packs.find(pack => pack.id === me.packId)?.name || '未選択')}</p></section>${me.shopInventory?.length ? shopInventoryHtml(me) : ''}</aside><main class="action-column"><section class="focus-panel"><span class="eyebrow">CURRENT ACTION</span><h2>${selected ? '対象を確認して最終確定' : '使用するカードを選択'}</h2>${stepsHtml(Boolean(selected), false)}<div class="card-hand">${me.cards.map(card => cardHtml(card, selected?.cardId === card.id, me)).join('')}</div>${selected ? selectionFormHtml(me, selected) : ''}</section></main></div>`; }
function stepsHtml(hasCard, confirmed) { return `<ol class="steps"><li class="${!hasCard ? 'active' : 'done'}"><b>1</b><span>カード選択</span></li><li class="${hasCard && !confirmed ? 'active' : confirmed ? 'done' : ''}"><b>2</b><span>対象選択</span></li><li class="${confirmed ? 'done' : hasCard ? 'active' : ''}"><b>3</b><span>最終確認</span></li></ol>`; }
function cardAvailability(card, me) {
  const extensionUntil = Number(me.cardMarks?.[card.id]?.cooldownExtensionUntil || 0);
  if (card.cooldownStatus === 'EXTENSION') {
    const remaining = Math.max(1, extensionUntil - state.globalTurnIndex + 1);
    return { unavailable: true, label: `強奪：あと${remaining}ターン使用不可`, reason: `【強奪】の効果により、あと${remaining}ターン使用できません。` };
  }
  if (card.cooldownStatus === 'NORMAL') {
    const reason = '前のターンに使用したため、このターンは使用できません。';
    return { unavailable: !card.bypassOptions?.length, label: card.bypassOptions?.length ? 'クールタイム：あと1ターン（CT無視可）' : 'クールタイム：あと1ターン', reason };
  }
  if (card.unavailableReason) return { unavailable: true, label: '使用不可', reason: card.id === 'encore' ? '再演できる使用履歴がありません。' : playerFacingText(card.unavailableReason) };
  return { unavailable: false, label: '使用可能', reason: null };
}
function cardHtml(card, selected, me) { const availability = cardAvailability(card, me); return `<article class="game-card ${card.category} ${selected ? 'selected' : ''} ${availability.unavailable ? 'unavailable' : ''}" tabindex="0"><div class="card-top"><span class="category ${card.category}">${esc(categoryName(card.category))}</span><span class="availability">${esc(availability.label)}</span></div><h3>${esc(card.name)}</h3><p>${esc(playerFacingText(card.description))}</p>${availability.unavailable ? `<button disabled>使用できません</button><details><summary>使用不能理由</summary><p class="pending">${esc(availability.reason)}</p></details>` : `<button data-card="${card.id}">${selected ? '選択中' : card.cooldownStatus === 'NORMAL' ? 'CT無視を使って選択' : 'このカードを選択'}</button>`}</article>`; }
function selectionFormHtml(me, selected) { const card = me.cards.find(item => item.id === selected.cardId); const targets = state.players.filter(player => player.participantId !== me.participantId); let control = ''; if (card.targetType === 'player') control = `<label>STEP 2　対象<select id="target">${targets.map(player => `<option value="${player.participantId}" ${selected.targetId === player.participantId ? 'selected' : ''}>PL${player.playerNumber} ${esc(player.name)}（HP ${player.hp}）</option>`).join('')}</select></label>`; else if (card.targetType.includes('Card')) { const candidates = me.cards.filter(item => item.id !== card.id && (card.targetType === 'ownAttackCard' ? item.category === 'attack' : item.category !== 'attack')); control = `<label>STEP 2　指定カード<select id="cardTarget">${candidates.map(item => `<option value="${item.id}" ${selected.cardTargetId === item.id ? 'selected' : ''}>${esc(item.name)}</option>`).join('')}</select></label>`; } else control = '<p class="step-note">STEP 2　対象選択はありません。</p>'; const targetStates = ['thaw','regression'].includes(card.id) ? (state.players.find(player => player.participantId === selected.targetId)?.ongoingEffects || []) : []; const stateControl = targetStates.length ? `<label>解除する持越状態<select id="stateKey">${targetStates.map(effect => `<option value="${effect.stackKey}" ${selected.stateKey === effect.stackKey ? 'selected' : ''}>${esc(statusDisplayName(effect.stackKey))}（値 ${effect.value}）</option>`).join('')}</select></label>` : ''; const encoreControl = card.id === 'encore' ? `<label>再演元<select id="copyUsage">${me.encoreCandidates.map(candidate => `<option value="${candidate.id}" ${selected.copyUsageId === candidate.id ? 'selected' : ''}>${esc(candidate.cardName)}（${esc(categoryName(candidate.kind === 'heal' ? 'heal' : candidate.kind === 'defense' ? 'defense' : 'attack'))}）</option>`).join('')}</select></label>` : ''; const bypassControl = card.cooldownStatus === 'NORMAL' && card.bypassOptions?.length ? `<label>CT無視手段<select id="ctBypass"><option value="">選択してください</option>${card.bypassOptions.map(option => `<option value="${option}" ${selected.ctBypass === option ? 'selected' : ''}>${({DESIRE:'欲印',GREEDY_TICKET:'欲張り札',HUNGER:'餓鬼地獄・強欲'}[option])}</option>`).join('')}</select></label>` : ''; return `<section class="confirm-panel"><h3>選択内容</h3><div class="selection-summary"><b>${esc(card.name)}</b><span>${selected.targetId ? playerName(selected.targetId) : selected.cardTargetId ? cardName(selected.cardTargetId) : '対象なし'}</span></div>${control}${stateControl}${encoreControl}${bypassControl}<button id="confirm" class="primary-action">STEP 3　この内容で最終確認</button></section>`; }
function waitingHtml(me) { const selected = mePublic(me.participantId).selection; const confirmed = state.players.filter(player => player.confirmed).length; return `<div class="waiting-layout"><section class="focus-panel waiting"><span class="eyebrow">WAITING</span><h2>最終確認済み</h2>${stepsHtml(true, true)}<div class="waiting-selection"><div><span>選択カード</span><b>${esc(cardName(selected?.cardId))}</b></div><div><span>対象</span><b>${selected?.targetId ? esc(playerName(selected.targetId)) : selected?.cardTargetId ? esc(cardName(selected.cardTargetId)) : 'なし'}</b></div></div><div class="confirm-count"><strong>${confirmed} / 7</strong><span>全体の確定人数</span></div><p>一斉公開までお待ちください。</p></section><aside class="side-column"><section class="panel compact-panel"><h2>他のPL</h2>${otherPlayersHtml(me.participantId)}</section>${me.shopInventory?.length ? shopInventoryHtml(me) : ''}</aside></div>`; }
function stationResultHtml() { return `<section class="focus-panel station-result"><span class="eyebrow">STATION RESULT</span><h2>${esc(state.station?.name || '駅')} 終了</h2><p>駅結果を確定しました。これから小鬼による報酬発表を行います。</p><p class="meta">順位、報酬、隠し特殊条件と達成者は、読み上げで順に公開されます。</p></section>`; }
function shopInventoryHtml(me) { const entries = [...(me.shopInventory || [])].sort((a, b) => String(a.acquiredAt || '').localeCompare(String(b.acquiredAt || ''))); return `<section class="panel owned-shop"><div class="owned-shop-heading"><span class="eyebrow">YOUR SHOP</span><h3>所持ショップカード</h3></div>${entries.length ? `<div class="owned-shop-cards">${entries.map(entry => `<article class="owned-shop-card ${entry.used ? 'used' : ''}"><div class="owned-shop-card-top"><span>SHOP CARD</span><em>${entry.used ? '使用済み' : '未使用'}</em></div><h4>${esc(entry.item.name)}</h4><p>${esc(playerFacingText(entry.item.effect))}</p></article>`).join('')}</div>` : '<p class="meta">所持しているショップカードはありません。</p>'}</section>`; }
function firstShopHtml(me) { const shop = state.shop; const accepting = state.timer && Date.now() < state.timer.endsAt; const items = [...shop.items].sort((a, b) => Number(a.soldOut) - Number(b.soldOut)); return `<section class="focus-panel shop-view"><span class="eyebrow">SHOP ${shop.id || ''}</span><h2>${esc(shop.name || 'ショップ')}</h2><p class="currency-wallet">所持冥貨：${currencySummary(me.currency)}</p><p class="meta">投入する冥貨の種類と枚数を選んでください。投入額が価格を超えた分はおつりとして返ります。</p><div class="shop-products">${items.map(item => { const disabled = item.soldOut || !accepting; const reason = item.soldOut ? 'SOLD OUT' : !accepting ? '購入受付終了' : ''; const paymentInputs = CURRENCY_TYPES.map(([type, label, value]) => `<label>${label}<small>（${value}）</small><input type="number" min="0" max="${me.currency[type] || 0}" value="0" inputmode="numeric" data-shop-coin="${item.id}" data-coin-type="${type}"></label>`).join(''); return `<article class="shop-product ${item.soldOut ? 'sold-out' : ''}"><span class="category">SHOP CARD</span><h3>${esc(item.name)}</h3><p>${esc(playerFacingText(item.effect))}</p><dl><div><dt>商品価格</dt><dd>${item.price}</dd></div><div><dt>在庫</dt><dd>${item.soldOut ? 'SOLD OUT' : '残り1'}</dd></div></dl><div class="shop-payment" data-shop-payment="${item.id}"><b>投入する冥貨</b><div class="shop-coin-inputs">${paymentInputs}</div><p>投入額：<strong data-shop-total="${item.id}">0</strong> ／ ${item.price}</p></div><button data-buy-shop="${item.id}" data-buy-player="${me.participantId}" data-shop-price="${item.price}" ${disabled ? 'disabled' : ''}>購入する</button><small class="purchase-reason" data-shop-reason="${item.id}">${reason}</small></article>`; }).join('')}</div>${shopInventoryHtml(me)}</section>`; }
function transferHtml(me) { const types = [['one','壱'],['two','弐'],['three','参'],['five','伍'],['seven','漆']].filter(([key]) => me.currency[key] > 0); const requests = state.transferRequests || []; return `<section class="panel transfer-view"><span class="eyebrow">GM REQUEST</span><h2>GMへ冥貨を譲渡申請</h2><p class="meta">譲渡先、冥貨の種類、枚数を指定してGMへ申請します。ココフォリア上の冥貨はGMの処理後に移動します。</p>${types.length ? `<form id="transferForm"><label>譲渡先<select name="recipientId">${state.players.filter(player => player.participantId !== me.participantId).map(player => `<option value="${player.participantId}">PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label><label>譲渡する冥貨<select name="currencyType">${types.map(([key,label]) => `<option value="${key}">${label}（所持 ${me.currency[key]}）</option>`).join('')}</select></label><label>枚数<input name="amount" type="number" min="1" value="1"></label><button class="primary-action" type="submit">GMへ譲渡申請</button></form>` : '<p class="meta">譲渡を申請できる冥貨を所持していません。</p>'}<div class="transfer-list"><h3>自分に関係する申請</h3>${requests.length ? requests.map(request => `<article><b>PL${request.senderNumber} → PL${request.recipientNumber}</b><span>${esc(request.currencyLabel)}×${request.amount}</span><em>${({PENDING:'GM確認待ち',CONFIRMED:request.cocofoliaApplied?'GM処理済み':'GM確定・ココフォリア未反映',REJECTED:'却下'}[request.status])}</em></article>`).join('') : '<p class="meta">譲渡申請はありません。</p>'}</div></section>`; }
function currencyHtml(me) { return `<section class="focus-panel"><span class="eyebrow">CURRENCY</span><h2>冥貨</h2><p class="currency-wallet">所持冥貨：${currencySummary(me.currency)}</p><p class="meta">譲渡はこの画面からGMへ申請してください。</p></section>${transferHtml(me)}${shopInventoryHtml(me)}`; }
function freeTimeHtml(me) { const ready = mePublic(me.participantId)?.freeTimeReady; const shopAvailable = state.shop.items.length > 0; const nav = `<nav class="free-time-nav"><button class="${freeTimeView === 'rest' ? 'active' : 'secondary'}" data-free-time-view="rest">休憩</button>${shopAvailable ? `<button class="${freeTimeView === 'shop' ? 'active' : 'secondary'}" data-free-time-view="shop">ショップ</button>` : ''}<button class="${freeTimeView === 'currency' ? 'active' : 'secondary'}" data-free-time-view="currency">冥貨</button></nav>`; if (freeTimeView === 'shop' && shopAvailable) return nav + firstShopHtml(me); if (freeTimeView === 'currency') return `${nav}${currencyHtml(me)}`; return `${nav}<section class="focus-panel waiting"><span class="eyebrow">FREE TIME</span><h2>${esc(state.station?.name || '')} 終了</h2><h3>自由時間</h3><div class="intro-timer">${timerHtml()}</div><p>${shopAvailable ? '休憩、相談、交渉、ショップ購入、冥貨の譲渡申請を行えます。' : '休憩、相談、交渉、冥貨の譲渡申請を行えます。'}</p><button id="freeTimeReady" data-ready-player="${me.participantId}" class="primary-action ${ready ? 'secondary' : ''}">${ready ? '準備完了を取り消す' : '準備完了'}</button><p class="meta">7人全員が準備完了しても自動では出発しません。</p></section>`; }
function testPlayerAction(participantId, playerAction) { return action('TEST_PLAYER_ACTION', { participantId, playerAction }); }
function bindFreeTimeNavigation() { const paymentFor = itemId => Object.fromEntries(CURRENCY_TYPES.map(([type]) => [type, Math.max(0, Number(document.querySelector(`[data-shop-coin="${itemId}"][data-coin-type="${type}"]`)?.value || 0))])); const changeFor = value => { let remaining = value; const coins = { one: 0, two: 0, three: 0, five: 0, seven: 0 }; for (const [type, , denomination] of [...CURRENCY_TYPES].reverse()) { coins[type] = Math.floor(remaining / denomination); remaining %= denomination; } return coins; }; const updatePayment = itemId => { const payment = paymentFor(itemId); const total = CURRENCY_TYPES.reduce((sum, [type, , value]) => sum + payment[type] * value, 0); const button = document.querySelector(`[data-buy-shop="${itemId}"]`); const price = Number(button?.dataset.shopPrice || 0); const totalNode = document.querySelector(`[data-shop-total="${itemId}"]`); const reasonNode = document.querySelector(`[data-shop-reason="${itemId}"]`); const unavailable = button?.closest('.shop-product')?.classList.contains('sold-out') || !state.timer || Date.now() >= state.timer.endsAt; if (totalNode) totalNode.textContent = String(total); if (!unavailable && button) button.disabled = total < price; if (!unavailable && reasonNode) reasonNode.textContent = total < price ? `あと${price - total}不足しています` : total > price ? `おつり：${currencyCoinsLabel(changeFor(total - price))}` : 'ちょうどです'; }; document.querySelectorAll('[data-free-time-view]').forEach(button => button.addEventListener('click', () => { freeTimeView = button.dataset.freeTimeView; render(); })); document.querySelectorAll('[data-shop-coin]').forEach(input => { input.addEventListener('input', () => { const itemId = input.dataset.shopCoin; const maximum = Number(input.max || 0); if (Number(input.value) > maximum) input.value = String(maximum); updatePayment(itemId); }); updatePayment(input.dataset.shopCoin); }); document.querySelectorAll('[data-buy-shop]').forEach(button => button.addEventListener('click', () => { const payment = paymentFor(button.dataset.buyShop); return state.me.role === 'GM' ? testPlayerAction(button.dataset.buyPlayer, { type: 'BUY_SHOP_ITEM', itemId: button.dataset.buyShop, payment }) : action('BUY_SHOP_ITEM', { itemId: button.dataset.buyShop, payment }); })); document.querySelector('#transferForm')?.addEventListener('submit', event => { event.preventDefault(); const me = state.me.role === 'PL' ? state.me : state.testPlayers?.find(player => player.participantId === previewParticipantId); const form = new FormData(event.currentTarget); const playerAction = { type: 'CREATE_TRANSFER_REQUEST', recipientId: form.get('recipientId'), currencyType: form.get('currencyType'), amount: Number(form.get('amount')) }; return state.me.role === 'GM' ? testPlayerAction(me.participantId, playerAction) : action('CREATE_TRANSFER_REQUEST', playerAction); }); document.querySelector('#freeTimeReady')?.addEventListener('click', buttonEvent => { const participantId = buttonEvent.currentTarget.dataset.readyPlayer; const ready = !mePublic(participantId)?.freeTimeReady; return state.me.role === 'GM' ? testPlayerAction(participantId, { type: 'SET_FREE_TIME_READY', ready }) : action('SET_FREE_TIME_READY', { ready }); }); }
function showPurchaseModal() { const me = state.me.role === 'PL' ? state.me : state.testMode ? state.testPlayers?.find(player => player.participantId === previewParticipantId) : null; if (!me?.purchaseNotice) return; const notice = me.purchaseNotice; const item = state.shop.items.find(entry => entry.id === notice.itemId); const transaction = me.purchaseTransactions?.find(entry => entry.id === notice.transactionId); if (!item || !transaction || document.querySelector('.purchase-modal-backdrop')) return; const paymentText = currencyCoinsLabel(transaction.payment); const changeText = transaction.change.total ? `${esc(transaction.change.label)}を受け取りました。` : 'おつりはありません。'; const primeChange = CURRENCY_TYPES.find(([type]) => ['two', 'three', 'five', 'seven'].includes(type) && transaction.change.coins[type]); const script = notice.firstPurchase && primeChange ? `<div class="purchase-story"><p class="dialogue">「お買い上げありがとうございま〜す！」</p><p class="dialogue">「${esc(paymentText)}をお預かりしま〜す！ 商品は${item.price}ですからぁ……」</p><p class="dialogue">「はいっ、おつりの【${primeChange[1]}】で〜す！」</p><p class="narration">小鬼が、一枚の冥貨を差し出す。</p><p class="narration">表には「${primeChange[1]}」。</p><p class="narration">これまで持っていた冥貨とは、少し形が違っている。</p></div>` : `<p>${esc(item.name)}を購入しました。${changeText}</p>`; document.body.insertAdjacentHTML('beforeend', `<div class="result-modal-backdrop purchase-modal-backdrop"><section class="result-modal purchase-modal" role="dialog" aria-modal="true" aria-label="購入結果"><span class="eyebrow">PURCHASE COMPLETE</span><h2>${esc(item.name)}</h2>${script}<button id="dismissPurchase" class="primary-action">確認して閉じる</button></section></div>`); document.querySelector('#dismissPurchase')?.addEventListener('click', () => state.me.role === 'GM' ? testPlayerAction(me.participantId, { type: 'DISMISS_PURCHASE_NOTICE' }) : action('DISMISS_PURCHASE_NOTICE')); }
function turnResultHtml(me) { const acknowledged = mePublic(me.participantId).confirmed; return `<div class="result-layout"><section class="focus-panel"><span class="eyebrow">TURN RESULT</span><h2>ターン処理結果</h2>${resultCardsHtml()}${acknowledged ? '<p class="success-message">結果確認を完了しました。ほかのPLをお待ちください。</p>' : '<button class="primary-action result-acknowledge">結果確認を完了</button>'}</section><aside class="side-column"><section class="status-card"><span>YOUR RESULT</span><h2>PL${me.playerNumber} ${esc(me.name)}</h2><div class="hp-large"><small>HP</small>${me.hp}<em>/ 15</em></div>${mePublic(me.participantId).isDeadState ? '<div class="dead-banner">亡者状態</div>' : '<div class="alive-banner">通常状態</div>'}</section>${me.shopInventory?.length ? shopInventoryHtml(me) : ''}</aside></div>`; }
function resultKey() { return `${state.station?.id || 'none'}:${state.globalTurnIndex}:${state.stationTurn}`; }
function resultCardsHtml() { return `<div class="result-cards">${state.revealedUsages.map(use => `<article class="result-card ${use.invalidated ? 'invalidated' : ''}"><div class="card-top"><span class="result-player">PL${use.playerNumber}</span><span class="category ${esc(use.category)}">${esc(categoryName(use.category))}</span></div><h3>${esc(use.cardName || cardName(use.cardId))}</h3><p>${esc(playerFacingText(use.description || '効果説明なし'))}</p><footer><span class="result-outcome ${use.invalidated ? 'failed' : ''}">${use.invalidated ? '無効化' : use.targetId ? `→ ${esc(playerName(use.targetId))}` : '成立'}</span></footer></article>`).join('') || '<p>公開されたカードはありません。</p>'}</div>`; }
function showResultModal() { const key = resultKey(); const existing = document.querySelector('.result-modal-backdrop'); if (state.phase !== 'TURN_RESULT' || dismissedResultKey === key) { existing?.remove(); return; } if (existing?.dataset.resultKey === key) return; existing?.remove(); const isPlayer = state.me.role === 'PL'; document.body.insertAdjacentHTML('beforeend', `<div class="result-modal-backdrop" data-result-key="${esc(key)}" role="presentation"><section class="result-modal" role="dialog" aria-modal="true" aria-labelledby="resultModalTitle"><span class="eyebrow">一斉公開</span><h2 id="resultModalTitle">TURN RESULT</h2><p class="result-modal-subtitle">${esc(state.station?.name || '')}　第${state.stationTurn}ターン</p>${resultCardsHtml()}<div class="result-hp-list">${state.players.map(player => `<span>PL${player.playerNumber}<b>HP ${player.hp}</b>${player.isDeadState ? '<em>亡者</em>' : ''}</span>`).join('')}</div><button class="primary-action close-result-modal">${isPlayer ? '結果確認を完了' : '結果を確認して閉じる'}</button></section></div>`); const modal = document.querySelector('.result-modal-backdrop'); modal?.querySelector('.close-result-modal')?.addEventListener('click', () => { dismissedResultKey = key; modal.remove(); if (isPlayer && !mePublic(state.me.participantId)?.confirmed) action('ACK_RESULT'); }); }
function otherPlayersHtml(ownId) { return `<div class="other-list">${state.players.filter(player => player.participantId !== ownId).map(player => `<details><summary><span>PL${player.playerNumber} ${esc(player.name)}</span><b>HP ${player.hp}</b>${player.isDeadState ? '<em>亡者</em>' : ''}</summary><p>${player.confirmed ? '最終確認済み' : '選択中'}</p></details>`).join('')}</div>`; }

function bindPlayer() { document.querySelector('#selfIntroDone')?.addEventListener('click', () => action('COMPLETE_SELF_INTRODUCTION')); }
function bindPack(me, preview) { document.querySelectorAll('[data-pack-choice]').forEach(button => button.addEventListener('click', () => preview ? action('TEST_SELECT_PACK', { participantId: me.participantId, packId: button.dataset.packChoice }) : action('SELECT_PACK', { packId: button.dataset.packChoice, confirmed: false }))); document.querySelector('#packClear')?.addEventListener('click', () => preview ? action('TEST_PLAYER_ACTION', { participantId: me.participantId, playerAction: { type: 'CLEAR_PACK_SELECTION' } }) : action('CLEAR_PACK_SELECTION')); document.querySelector('#packConfirm')?.addEventListener('click', () => !preview && action('SELECT_PACK', { packId: me.packId, confirmed: true })); }
function playerAction(me, preview, playerAction) { return preview ? action('TEST_PLAYER_ACTION', { participantId: me.participantId, playerAction }) : action(playerAction.type, playerAction); }
function updateSelection(me, preview, changes) { const selected = mePublic(me.participantId).selection; playerAction(me, preview, { type: 'SELECT_CARD', ...selected, ...changes }); }
function bindTurn(me, preview) { document.querySelectorAll('[data-card]').forEach(button => button.addEventListener('click', () => chooseCard(me, preview, button.dataset.card))); document.querySelector('#target')?.addEventListener('change', event => updateSelection(me, preview, { targetId: event.target.value })); document.querySelector('#cardTarget')?.addEventListener('change', event => updateSelection(me, preview, { cardTargetId: event.target.value })); document.querySelector('#stateKey')?.addEventListener('change', event => updateSelection(me, preview, { stateKey: event.target.value })); document.querySelector('#copyUsage')?.addEventListener('change', event => updateSelection(me, preview, { copyUsageId: event.target.value })); document.querySelector('#ctBypass')?.addEventListener('change', event => updateSelection(me, preview, { ctBypass: event.target.value || null })); document.querySelector('#confirm')?.addEventListener('click', () => playerAction(me, preview, { type: 'CONFIRM_CARD' })); document.querySelector('.result-acknowledge')?.addEventListener('click', () => playerAction(me, preview, { type: 'ACK_RESULT' })); }
function chooseCard(me, preview, cardId) { const card = me.cards.find(item => item.id === cardId); const payload = { type: 'SELECT_CARD', cardId }; if (card.targetType === 'player') payload.targetId = state.players.find(player => player.participantId !== me.participantId)?.participantId; else if (card.targetType.includes('Card')) payload.cardTargetId = me.cards.find(item => item.id !== cardId && (card.targetType === 'ownAttackCard' ? item.category === 'attack' : item.category !== 'attack'))?.id; if (card.bypassOptions?.length) { const options = card.bypassOptions.map(option => ({DESIRE:'欲印',GREEDY_TICKET:'欲張り札',HUNGER:'餓鬼地獄・強欲'}[option])).join(' / '); const choice = prompt(`通常CT中です。使用するCT無視手段を入力してください：${options}`, options); const map = {欲印:'DESIRE',欲張り札:'GREEDY_TICKET','餓鬼地獄・強欲':'HUNGER'}; payload.ctBypass = map[choice] || choice; } if (card.id === 'encore') { const candidate = me.encoreCandidates.at(-1); payload.copyUsageId = candidate?.id; payload.copyKind = candidate?.kind; } playerAction(me, preview, payload); }
function bindPreview(me) { document.querySelector('#previewBack')?.addEventListener('click', () => { previewParticipantId = null; render(); }); document.querySelector('[data-test-self-intro]')?.addEventListener('click', () => action('TEST_COMPLETE_SELF_INTRODUCTION', { participantId: me.participantId })); }

function renderGm() { app.innerHTML = gameHeaderHtml('GM CONTROL') + gmViewerBarHtml() + gmNavHtml() + `<section class="gm-shell">${gmTabContent()}</section>` + previewOverlayHtml(); bindGm(); bindPrimaryNarrativeControls(); bindGameGuide(); addGameGuideTestOption(); bindPurchaseCurrencyReflection(); }
function gmViewerBarHtml() { return `<section class="viewer-bar"><label>ユーザー画面を見る<select id="preview"><option value="">選択してください</option>${state.players.map(player => `<option value="${player.participantId}" ${previewParticipantId === player.participantId ? 'selected' : ''}>PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label><span>GM画面を残したまま確認できます</span></section>`; }
function previewOverlayHtml() { if (!previewParticipantId) return ''; const me = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (!me) return ''; let content = ''; if (state.phase === 'INTRODUCTION') content = introductionHtml(); else if (state.phase === 'GAME_GUIDE') content = gameGuideHtml(); else if (state.phase === 'STATION_INTRODUCTION') content = stationIntroductionHtml(); else if (state.phase === 'SELF_INTRODUCTION') content = selfIntroductionHtml(me.participantId); else if (state.phase === 'PACK_SELECTION') content = packSelectionHtml(me, true); else if (state.phase === 'LOBBY') content = '<section class="panel"><h2>乗車待機中</h2></section>'; else if (state.phase === 'STATION_RESULT') content = stationResultHtml(); else if (state.phase === 'REWARD_NARRATION') content = rewardNarrationHtml(); else if (state.phase === 'CURRENCY_SYNC_WAIT') content = currencySyncWaitHtml(me); else if (state.phase === 'FREE_TIME_INTRO') content = freeTimeIntroductionHtml(); else if (state.phase === 'FREE_TIME') content = freeTimeHtml(me); else content = state.phase === 'TURN_RESULT' ? turnResultHtml(me) : mePublic(me.participantId).confirmed ? waitingHtml(me) : selectionWorkspaceHtml(me); return `<div class="preview-overlay" role="dialog" aria-modal="true" aria-label="PL画面プレビュー"><section class="preview-window"><header><div><span class="eyebrow">USER VIEW</span><h2>PL${me.playerNumber} ${esc(me.name)} の画面</h2></div><button id="previewClose" class="secondary">閉じる</button></header>${gameHeaderHtml(`PL${me.playerNumber} PREVIEW`)}<div class="preview-body ${state.testMode ? '' : 'read-only'}">${content}</div>${state.testMode ? '<p class="preview-note">テストルームでは、この画面からPL操作も行えます。</p>' : '<p class="preview-note">通常ルームでは閲覧専用です。</p>'}</section></div>`; }
function gmNavHtml() { const tabs = [['progress', '進行'], ['players', 'PL管理'], ['currency', '冥貨'], ['shop', 'ショップ'], ['test', 'テスト']]; return `<nav class="gm-tabs" aria-label="GM情報管理">${tabs.map(([id, label]) => `<button data-gm-tab="${id}" class="${gmTab === id ? 'active' : ''}" ${id === 'test' && !state.testMode ? 'disabled' : ''}>${label}</button>`).join('')}</nav>`; }
function gmTabContent() { if (gmTab === 'players') return gmPlayersPanel(); if (gmTab === 'currency') return gmCurrencyPanel(); if (gmTab === 'shop') return gmShopPanel(); if (gmTab === 'test') return `<section class="panel"><h2>テスト機能</h2>${testNavigationHtml()}${state.phase === 'PACK_SELECTION' ? testPackSelection() : ''}${state.testMode ? '<button id="grantCurrency" class="secondary">全PLの壱を20枚にする</button>' : ''}</section>`; return gmProgressPanel(); }
function gmCurrencySyncPanel() { const transactions = state.stationCurrencyTransactions || []; const sync = state.currencySync || { total: transactions.length, pending: transactions.filter(item => !item.cocofoliaApplied).length }; const grouped = new Map(); for (const transaction of transactions) grouped.set(transaction.participantId, [...(grouped.get(transaction.participantId) || []), transaction]); return `<section class="panel currency-sync-panel"><div class="section-heading"><h2>ココフォリア反映確認</h2><span>GM専用</span></div><div class="currency-sync-count"><strong>反映済み ${sync.total - sync.pending}件</strong><b>未反映：${sync.pending}件</b></div>${sync.pending === 0 ? '<p class="success-message">ココフォリアへの冥貨反映が完了しました。未反映：0件</p>' : '<p class="meta">ココフォリアで冥貨を渡した後、対応する報酬を反映済みにしてください。</p>'}${[...grouped.entries()].map(([participantId, entries]) => `<article class="currency-sync-player"><header><b>PL${entries[0].playerNumber} ${esc(entries[0].playerName || '')}</b>${entries.some(entry => !entry.cocofoliaApplied) ? `<button class="secondary small" data-mark-player-station-rewards="${participantId}">このPLをすべて反映済み</button>` : '<span class="pill confirmed">すべて反映済み</span>'}</header>${entries.map(entry => `<div><span>${esc(entry.label || '報酬')}　壱×${entry.amount}</span>${entry.cocofoliaApplied ? '<span class="pill confirmed">反映済み</span>' : `<button class="secondary small" data-mark-station-reward="${entry.id}">反映済み</button>`}</div>`).join('')}</article>`).join('') || '<p class="meta">今回の冥貨報酬はありません。</p>'}</section>`; }
function gmProgressPanel() { const confirmed = state.players.filter(player => player.confirmed).length; const pending = state.players.filter(player => !player.confirmed).map(player => `PL${player.playerNumber}`).join('、') || 'なし'; const duplicates = duplicatePackNames(); const resultPhase = state.phase === 'TURN_RESULT'; const pendingPurchaseCurrencies = state.purchaseTransactions?.filter(item => !item.currencyCocofoliaApplied).length || 0; const pendingTransfers = state.transferRequests?.filter(item => item.status === 'PENDING' || (item.status === 'CONFIRMED' && !item.cocofoliaApplied)).length || 0; const ready = state.players.filter(player => player.freeTimeReady).length; return `<div class="gm-progress"><section class="focus-panel gm-action"><span class="eyebrow">NEXT ACTION</span><h2>${gmInstruction()}</h2><div class="primary-control">${gmActions(confirmed)}</div>${state.phase === 'PACK_SELECTION' && duplicates.length ? `<p class="pack-warning">重複中：<b>${esc(duplicates.join('、'))}</b>　PL管理から確定を解除して選び直してください。</p>` : ''}${['PACK_SELECTION','TURN_SELECTION','TURN_RESULT'].includes(state.phase) ? `<p class="pending-list">${resultPhase ? '結果未確認' : '未確定'}PL：<b>${pending}</b></p>` : ''}${state.phase === 'FREE_TIME' ? `<p class="pending-list">準備完了：<b>${ready}/7</b></p>${pendingPurchaseCurrencies || pendingTransfers ? `<p class="pack-warning">未処理・未反映の冥貨：購入 ${pendingPurchaseCurrencies}件／譲渡 ${pendingTransfers}件</p>` : '<p class="success-message">未処理・未反映の冥貨：0件</p>'}` : ''}</section>${state.phase === 'STATION_RESULT' ? stationResultHtml() : ''}${state.phase === 'REWARD_NARRATION' ? rewardNarrationHtml() + rewardNarrationAdvanceHtml() : ''}${state.phase === 'CURRENCY_SYNC_WAIT' ? gmCurrencySyncPanel() : ''}${state.phase === 'FREE_TIME_INTRO' ? freeTimeIntroductionHtml() + freeTimeIntroductionAdvanceHtml() : ''}${state.phase === 'INTRODUCTION' ? introductionHtml() + introductionAdvanceHtml() : ''}${state.phase === 'GAME_GUIDE' ? gameGuideHtml() + gameGuideAdvanceHtml() : ''}${state.phase === 'STATION_INTRODUCTION' ? stationIntroductionHtml() + stationIntroductionAdvanceHtml() : ''}${state.phase === 'SELF_INTRODUCTION' ? selfIntroductionHtml() : ''}</div>`; }
function duplicatePackNames() { const counts = new Map(); state.players.forEach(player => { if (player.packId) counts.set(player.packId, (counts.get(player.packId) || 0) + 1); }); return [...counts].filter(([, count]) => count > 1).map(([packId]) => state.packs.find(pack => pack.id === packId)?.name || packId); }
function gmInstruction() { if (state.phase === 'LOBBY') return '7人の参加後、導入を開始'; if (state.phase === 'INTRODUCTION') return '導入を読み進める'; if (state.phase === 'GAME_GUIDE') return 'ゲーム説明を読み進める'; if (state.phase === 'STATION_INTRODUCTION') return `${state.station?.name || '次の地獄'}の説明を読み進める`; if (state.phase === 'SELF_INTRODUCTION') return '全員の自己紹介完了を待つ'; if (state.phase === 'PACK_SELECTION') return '全員のパック確定を待つ'; if (state.phase === 'TURN_SELECTION') return '全員の最終確認後、一斉公開する'; if (state.phase === 'STATION_RESULT') return '駅結果を確認して報酬発表を開始'; if (state.phase === 'REWARD_NARRATION') return '小鬼による報酬発表を読み進める'; if (state.phase === 'CURRENCY_SYNC_WAIT') return 'ココフォリアへの冥貨反映を確認する'; if (state.phase === 'FREE_TIME_INTRO') return '自由時間の案内を読み進める'; if (state.phase === 'FREE_TIME') return '自由時間終了後、次の地獄へ進む'; return '結果確認後、次のターンへ進む'; }
function gmPlayersPanel() { return `<section class="panel"><div class="section-heading"><h2>PL管理</h2><span>HP補正・確定解除</span></div>${gmStatusTable(true)}</section>`; }
function gmCooldownHtml(playerId) { const holder = state.testPlayers?.find(player => player.participantId === playerId); const blockedCards = holder?.cards?.filter(card => ['EXTENSION', 'NORMAL'].includes(card.cooldownStatus)) || []; if (!blockedCards.length) return ''; return `<div class="gm-cooldown"><small>使用制限</small>${blockedCards.map(card => `<span>${esc(card.name)}：${esc(cardAvailability(card, holder).label)}</span>`).join('')}</div>`; }
function gmChoiceHtml(player) { const cooldown = gmCooldownHtml(player.participantId); if (state.phase === 'PACK_SELECTION') { const pack = state.packs.find(item => item.id === player.packId); return `<div class="gm-choice"><small>選択パック</small><b>${esc(pack?.name || '未選択')}</b>${cooldown}</div>`; } if (state.phase === 'TURN_SELECTION') { const selection = player.selection; if (!selection) return `<div class="gm-choice"><small>今回の選択</small><b>未選択</b>${cooldown}</div>`; const card = state.packs.flatMap(pack => pack.cards || []).find(item => item.id === selection.cardId); const target = state.players.find(item => item.participantId === selection.targetId); return `<div class="gm-choice"><small>今回の選択</small><b>${esc(card?.name || selection.cardId)}</b><span>対象：${esc(target ? `PL${target.playerNumber} ${target.name}` : '対象なし')}</span>${cooldown}</div>`; } return cooldown ? `<div class="gm-choice">${cooldown}</div>` : '<div class="gm-choice"></div>'; }
function gmStatusTable(manage) { const resultPhase = state.phase === 'TURN_RESULT'; return `<div class="gm-player-table">${state.players.map(player => `<article><div class="player-id"><span>PL${player.playerNumber}</span><b>${esc(player.name)}</b></div>${gmChoiceHtml(player)}<strong class="mini-hp">HP ${player.hp}</strong>${player.isDeadState ? '<span class="pill dead">亡者</span>' : '<span class="pill alive">通常</span>'}<span class="pill ${player.confirmed ? 'confirmed' : 'pending'}">${player.confirmed ? (resultPhase ? '確認済み' : '確定') : (resultPhase ? '未確認' : '未確定')}</span>${manage ? `<div class="row-actions">${player.confirmed && !resultPhase ? `<button class="secondary small" data-unlock="${player.participantId}">確定解除</button>` : ''}<button class="secondary small" data-hp="${player.participantId}" data-current="${player.hp}">HP補正</button></div>` : ''}</article>`).join('')}</div>`; }
function gmCurrencyPanel() { const transfers = state.transferRequests || []; return `<section class="panel"><div class="section-heading"><h2>冥貨・所持SHOP</h2><span>GM専用</span></div><div class="currency-grid">${state.testPlayers?.map(player => `<article><b>PL${player.playerNumber} ${esc(player.name)}</b><p>${currencySummary(player.currency)}</p><small>所持SHOP：${player.shopInventory.length ? player.shopInventory.map(entry => esc(entry.item.name)).join('、') : 'なし'}</small></article>`).join('') || '<p>冥貨の詳細はGM専用情報です。</p>'}</div><div class="transfer-admin"><h2>GMによる譲渡処理</h2><p class="meta">PLの申請を確認してWeb上の譲渡を確定し、ココフォリアで冥貨を移動した後に処理済みをチェックします。</p>${transfers.length ? transfers.map(request => `<article><div><b>PL${request.senderNumber} ${esc(request.senderName)} → PL${request.recipientNumber} ${esc(request.recipientName)}</b><p>${esc(request.currencyLabel)}×${request.amount}</p></div><span class="pill ${request.status === 'CONFIRMED' ? 'confirmed' : 'pending'}">${request.status === 'PENDING' ? 'GM確認待ち' : request.status === 'REJECTED' ? '却下' : request.cocofoliaApplied ? 'GM処理済み' : 'GM確定・ココフォリア未反映'}</span>${request.status === 'PENDING' ? `<div class="row-actions"><button data-approve-transfer="${request.id}">譲渡を確定</button><button class="secondary" data-reject-transfer="${request.id}">却下</button></div>` : request.status === 'CONFIRMED' && !request.cocofoliaApplied ? `<button class="secondary" data-mark-transfer="${request.id}">ココフォリアで処理済み ✓</button>` : ''}</article>`).join('') : '<p class="meta">譲渡申請はありません。</p>'}</div></section>`; }
function gmShopPanel() { const transactions = state.purchaseTransactions || []; return `<section class="panel"><div class="section-heading"><h2>${esc(state.shop.name || 'ショップ管理')}</h2><span>SHOPはWeb管理</span></div><p class="meta">PLが選んだ冥貨を受け取り、超過分のおつりを渡します。ココフォリアで反映するのは冥貨だけです。</p><div class="shop-stock-summary">${state.shop.items.map(item => `<span>${esc(item.name)}：${item.soldOut ? 'SOLD OUT' : '在庫1'}</span>`).join('') || '<span>現在はショップを開いていません。</span>'}</div><div class="purchase-transactions">${transactions.length ? transactions.map(transaction => `<article><div><b>PL${transaction.playerNumber} ${esc(transaction.playerName)}</b><strong>${esc(transaction.itemName)}購入</strong></div><p>ココフォリア冥貨：${esc(currencyCoinsLabel(transaction.payment))}を使用<br>おつり：${esc(transaction.change.label)}</p><span class="pill ${transaction.currencyCocofoliaApplied ? 'confirmed' : 'pending'}">冥貨：${transaction.currencyCocofoliaApplied ? '反映済み' : '未反映'}</span>${transaction.currencyCocofoliaApplied ? '' : `<button class="secondary" data-mark-purchase-currency="${transaction.id}">冥貨の反映済み</button>`}</article>`).join('') : '<p class="meta">購入取引はありません。</p>'}</div></section>`; }
function placeholderPanel(title, text) { return `<section class="panel empty-state"><span class="eyebrow">${esc(title)}</span><h2>準備中</h2><p>${esc(text)}</p></section>`; }
function gmActions(confirmed) { const nextStation = state.stations[state.stations.findIndex(item => item.id === state.station?.id) + 1]; if (state.phase === 'LOBBY') return `<button id="openIntro" class="primary-action" ${state.players.length !== 7 ? 'disabled' : ''}>導入を開始</button>`; if (state.phase === 'INTRODUCTION') return '<p>画面下の「次へ」で導入を進めてください。</p>'; if (state.phase === 'GAME_GUIDE') return '<p>画面下の「次へ」でゲーム説明を進めてください。</p>'; if (state.phase === 'STATION_INTRODUCTION') return `<p>画面下の「次へ」で${esc(state.station?.name || '次の地獄')}の説明を進めてください。</p>`; if (state.phase === 'SELF_INTRODUCTION') { const allDone = state.players.every(player => player.selfIntroductionComplete); const timeUp = Date.now() >= state.timer.endsAt; return `<button id="openGameGuide" class="primary-action" ${allDone || timeUp ? '' : 'disabled'}>${allDone && !timeUp ? '全員完了：ゲーム説明へ' : 'ゲーム説明へ進む'}</button>`; } if (state.phase === 'PACK_SELECTION') { const unique = state.players.every(player => player.packId) && new Set(state.players.map(player => player.packId)).size === 7; return `<button id="start" class="primary-action" ${confirmed === 7 && unique ? '' : 'disabled'}>第一・焦熱地獄を開始</button>`; } if (state.phase === 'TURN_SELECTION') return `<button id="reveal" class="primary-action" ${confirmed !== 7 ? 'disabled' : ''}>一斉公開して処理</button>`; if (state.phase === 'STATION_RESULT') return '<button id="startRewardNarration" class="primary-action">報酬発表を開始</button>'; if (state.phase === 'REWARD_NARRATION') return '<p>画面下の「次へ」で報酬発表を進めてください。</p>'; if (state.phase === 'CURRENCY_SYNC_WAIT') return `<button id="startFreeTime" class="primary-action">自由時間を開始する</button>`; if (state.phase === 'FREE_TIME_INTRO') return '<p>画面下の「次へ」で自由時間の案内を進めてください。</p>'; if (state.phase === 'FREE_TIME') return `<button id="startNextStation" class="primary-action" ${nextStation ? '' : 'disabled'}>${nextStation ? `${esc(nextStation.name)}へ` : '次の地獄はありません'}</button>`; return `<div class="actions">${state.testMode ? '<button id="ackAllResults" class="secondary">全PLの結果確認を一括完了</button>' : ''}<button id="next" class="primary-action" ${confirmed !== 7 ? 'disabled' : ''}>次ターンへ</button></div>`; }
function testNavigationHtml() { const fixed = [['INTRODUCTION', '導入'], ['SELF_INTRODUCTION', '自己紹介'], ['PACK_SELECTION', 'パック選択']]; const stationPhases = state.stations.flatMap((station, stationIndex) => { const turns = Array.from({ length: station.turnCount }, (_, index) => [['TURN_SELECTION', `${station.name} 第${index + 1}ターン・カード選択`], ['TURN_RESULT', `${station.name} 第${index + 1}ターン・結果`]].map(([phase, label]) => [`${phase}:${stationIndex}:${index + 1}`, label])).flat(); const stationIntro = [[`STATION_INTRODUCTION:${stationIndex}:0`, `${station.name}へ・駅導入`]]; return stationIndex < state.stations.length - 1 ? [...stationIntro, ...turns, [`FREE_TIME:${stationIndex}:0`, `${station.name}終了後・自由時間（休憩5分）`]] : [...stationIntro, ...turns]; }); const current = state.station ? `${state.phase}:${state.stations.findIndex(item => item.id === state.station.id)}:${['FREE_TIME', 'STATION_INTRODUCTION'].includes(state.phase) ? 0 : state.stationTurn}` : state.phase; return `<label>移動先<select id="testPhase">${[...fixed, ...stationPhases].map(([value, label]) => `<option value="${value}" ${value === current ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select></label><div class="actions"><button id="jumpPhase">フェーズ移動</button>${state.phase === 'PACK_SELECTION' ? '<button class="secondary" id="autofillPacks">全PLへパックを自動割り当て</button>' : ''}${state.phase === 'TURN_SELECTION' ? '<button class="secondary" id="autofill">全PLを自動選択・確定</button><button class="secondary" id="timerReset">タイマーを戻す</button>' : ''}${state.phase === 'TURN_RESULT' ? '<button class="secondary" id="ackAllResults">全PLの結果確認を一括完了</button>' : ''}</div><p class="meta">移動時は未確定の選択と公開結果を消去します。</p>`; }
function testPackSelection() { return `<details><summary>PL別パック割り当て</summary><div class="pack-admin">${state.players.map(player => `<label>PL${player.playerNumber}<select data-test-pack="${player.participantId}"><option value="">未選択</option>${state.packs.map(pack => `<option value="${pack.id}" ${player.packId === pack.id ? 'selected' : ''}>${esc(pack.name)}</option>`).join('')}</select></label>`).join('')}</div></details>`; }
function bindGm() { document.querySelectorAll('[data-gm-tab]').forEach(button => button.addEventListener('click', () => { gmTab = button.dataset.gmTab; render(); })); document.querySelector('#openIntro')?.addEventListener('click', () => action('OPEN_INTRODUCTION')); document.querySelector('#advanceIntro')?.addEventListener('click', () => action('ADVANCE_INTRODUCTION')); document.querySelector('#advanceStationIntro')?.addEventListener('click', () => action('ADVANCE_STATION_INTRODUCTION')); document.querySelector('#startRewardNarration')?.addEventListener('click', () => action('START_REWARD_NARRATION')); document.querySelector('#advanceRewardNarration')?.addEventListener('click', () => action('ADVANCE_REWARD_NARRATION')); document.querySelector('#advanceFreeTimeIntroduction')?.addEventListener('click', () => action('ADVANCE_FREE_TIME_INTRODUCTION')); document.querySelector('#openPacks')?.addEventListener('click', () => action('OPEN_PACK_SELECTION')); document.querySelector('#start')?.addEventListener('click', () => action('START_FIRST_STATION')); document.querySelector('#reveal')?.addEventListener('click', () => action('REVEAL_AND_RESOLVE')); document.querySelector('#next')?.addEventListener('click', () => action('NEXT_TURN')); document.querySelector('#startFreeTime')?.addEventListener('click', () => action('START_FREE_TIME')); document.querySelector('#startNextStation')?.addEventListener('click', () => action('START_NEXT_STATION')); document.querySelector('#autofillPacks')?.addEventListener('click', () => action('TEST_AUTOFILL_PACKS')); document.querySelector('#autofill')?.addEventListener('click', () => action('TEST_AUTOFILL_TURN')); document.querySelector('#ackAllResults')?.addEventListener('click', () => action('TEST_ACK_ALL_RESULTS')); document.querySelector('#grantCurrency')?.addEventListener('click', () => action('TEST_GRANT_ONE_CURRENCY')); document.querySelector('#timerReset')?.addEventListener('click', () => action('SET_TIMER', { seconds: 180 })); document.querySelector('#jumpPhase')?.addEventListener('click', () => { const [phase, stationIndex, stationTurn] = document.querySelector('#testPhase').value.split(':'); action('TEST_JUMP_PHASE', { phase, stationIndex: Number(stationIndex), stationTurn: Number(stationTurn) }); }); document.querySelectorAll('[data-mark-station-reward]').forEach(button => button.addEventListener('click', () => action('MARK_CURRENCY_TRANSACTION_APPLIED', { transactionId: button.dataset.markStationReward }))); document.querySelectorAll('[data-mark-player-station-rewards]').forEach(button => button.addEventListener('click', () => action('MARK_PLAYER_STATION_REWARDS_APPLIED', { participantId: button.dataset.markPlayerStationRewards }))); document.querySelector('#preview')?.addEventListener('change', event => { previewParticipantId = event.target.value || null; render(); }); document.querySelector('#previewClose')?.addEventListener('click', () => { previewParticipantId = null; render(); }); document.querySelectorAll('[data-test-pack]').forEach(select => select.addEventListener('change', () => select.value && action('TEST_SELECT_PACK', { participantId: select.dataset.testPack, packId: select.value }))); document.querySelectorAll('[data-mark-purchase]').forEach(button => button.addEventListener('click', () => action('MARK_PURCHASE_APPLIED', { transactionId: button.dataset.markPurchase }))); document.querySelectorAll('[data-approve-transfer]').forEach(button => button.addEventListener('click', () => action('APPROVE_TRANSFER', { transferId: button.dataset.approveTransfer }))); document.querySelectorAll('[data-reject-transfer]').forEach(button => button.addEventListener('click', () => action('REJECT_TRANSFER', { transferId: button.dataset.rejectTransfer }))); document.querySelectorAll('[data-mark-transfer]').forEach(button => button.addEventListener('click', () => action('MARK_TRANSFER_APPLIED', { transferId: button.dataset.markTransfer }))); document.querySelectorAll('[data-unlock]').forEach(button => button.addEventListener('click', () => action('UNLOCK_PLAYER', { participantId: button.dataset.unlock }))); document.querySelectorAll('[data-hp]').forEach(button => button.addEventListener('click', () => { const hp = prompt('補正後HP（0～15）', button.dataset.current); if (hp !== null) action('ADJUST_HP', { participantId: button.dataset.hp, hp: Number(hp), reason: 'GMテスト用補正' }); })); const previewMe = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (previewMe && state.testMode) { if (state.phase === 'PACK_SELECTION') bindPack(previewMe, true); else if (['TURN_SELECTION', 'TURN_RESULT'].includes(state.phase)) bindTurn(previewMe, true); bindPreview(previewMe); } }

function bindGameGuide() { document.querySelector('#openGameGuide')?.addEventListener('click', () => action('OPEN_GAME_GUIDE')); document.querySelector('#advanceGameGuide')?.addEventListener('click', () => action('ADVANCE_GAME_GUIDE')); }
function bindPrimaryNarrativeControls() { const control = document.querySelector('.gm-action .primary-control'); if (!control) return; const configuration = state.phase === 'INTRODUCTION' ? { type: 'ADVANCE_INTRODUCTION', label: state.introductionStep >= INTRODUCTION_LINES.length ? '自己紹介8分へ' : '次へ' } : state.phase === 'GAME_GUIDE' ? { type: 'ADVANCE_GAME_GUIDE', label: state.gameGuide?.step >= state.gameGuide?.lines.length ? 'パック選択へ' : '次へ' } : state.phase === 'STATION_INTRODUCTION' ? { type: 'ADVANCE_STATION_INTRODUCTION', label: state.stationIntroduction?.step >= state.stationIntroduction?.lines.length ? `${state.station?.name || '次の地獄'}を開始` : '次へ' } : state.phase === 'REWARD_NARRATION' ? { type: 'ADVANCE_REWARD_NARRATION', label: state.rewardNarration?.step >= state.rewardNarration?.lines.length ? '冥貨反映待機へ' : '次へ' } : state.phase === 'FREE_TIME_INTRO' ? { type: 'ADVANCE_FREE_TIME_INTRODUCTION', label: state.freeTimeIntroduction?.step >= state.freeTimeIntroduction?.lines.length ? '自由時間を開始' : '次へ' } : null; if (!configuration) return; control.innerHTML = `<button type="button" id="primaryNarrativeAdvance" class="primary-action">${esc(configuration.label)}</button>`; control.querySelector('#primaryNarrativeAdvance')?.addEventListener('click', () => action(configuration.type)); }
function addGameGuideTestOption() { const selector = document.querySelector('#testPhase'); if (!selector || selector.querySelector('[value="GAME_GUIDE"]')) return; const option = new Option('ゲーム説明', 'GAME_GUIDE', false, state.phase === 'GAME_GUIDE'); selector.add(option, 2); }
function bindPurchaseCurrencyReflection() { document.querySelectorAll('[data-mark-purchase-currency]').forEach(button => button.addEventListener('click', () => action('MARK_PURCHASE_CURRENCY_APPLIED', { transactionId: button.dataset.markPurchaseCurrency }))); }

request('/api/config').then(config => { if (config.testRoomsEnabled) document.querySelector('#testRoom')?.removeAttribute('hidden'); }).catch(() => {});
